(function(root){
'use strict';const C=typeof module!=='undefined'?require('./core.js'):root.UAV,F=typeof module!=='undefined'?require('./flight-controls.js'):root.FlightControls;
const cost=(route,speed)=>C.length(route)*.0016+C.length(route)/speed*.001;
function descent(alt,target){if(!Number.isFinite(alt)||!Number.isFinite(target)||target>alt)return null;let h=alt,seconds=0;while(h>target+.001&&seconds<2000){const n=F.landing(h,target,.05);h=n.altitude;seconds+=.05;}return {seconds,cost:seconds*.001+Math.max(0,alt-target)*.001+.002};}
async function prepare({mission:m,origin,home,required,optional,battery,speed,plan,landingTarget,altitude=60,active=()=>true}){
 const first=await plan(origin,required),p4=first.at(-1),back=await plan(p4,home),visit=await plan(p4,optional),p5=visit.at(-1),last=await plan(p5,home);if(!active())throw Error('规划已取消');if(Math.hypot(back.at(-1)[0]-home[0],back.at(-1)[1]-home[1])>2||Math.hypot(last.at(-1)[0]-home[0],last.at(-1)[1]-home[1])>2)throw Error('起降点无法安全到达');
 const landing=descent(altitude,landingTarget);if(!landing)throw Error('尚未提供可用的返航降落面');const reduced=first.concat(back.slice(1)),full=first.concat(visit.slice(1),last.slice(1)),a=cost(reduced,speed)+landing.cost,b=cost(full,speed)+landing.cost;if(b<=a+.05)throw Error('可选任务未产生足够的资源差异');const injected=Math.min(battery,15+(a+b)/2);if(injected-a<15)throw Error('当前电量不足以完成必需任务并返航');
 m.destination={id:'home',name:'A · 起降区',point:home.slice()};m.resourceTasks=[{id:'P4',name:'P4 · 必需巡检',priority:'必需',point:p4},{id:'P5',name:'P5 · 可选巡检',priority:'可选',point:p5}];m.taskPriorities={P4:'必需',P5:'可选'};m.route=reduced;m.initialRoute=full;m.alternative=full;m.resourcePrepared=true;m.battery=injected;m.returnPoint=home.slice();m.landingTargetAltitude=landingTarget;m.resourceCruiseAltitude=altitude;m.resourceEnergy={original:injected-b,adjusted:injected-a,originalSeconds:C.length(full)/speed+landing.seconds,adjustedSeconds:C.length(reduced)/speed+landing.seconds};return {route:reduced,battery:injected};
}
function validate(route,tasks,done,home,budget=null){const errors=[];for(const t of tasks.filter(t=>t.priority==='必需'&&!done.includes(t.id))){const p=C.nearestPointOnRoute(route,t.point);if(!p||p.distance>2)errors.push('航线必须经过必需任务点 '+t.id)}if(Math.hypot(route.at(-1)[0]-home[0],route.at(-1)[1]-home[1])>2)errors.push('任务航线必须返回 A 点');if(budget&&budget.battery-cost(route,budget.speed)-(budget.landing?.cost||0)<15)errors.push('预计返航着陆余电低于15%');if(budget&&Number.isFinite(budget.remainingTime)&&C.length(route)/budget.speed+(budget.landing?.seconds||0)>budget.remainingTime)errors.push('预计完成晚于任务截止时刻');return errors;}
const api={prepare,validate,cost,descent};if(typeof module!=='undefined')module.exports=api;else root.ResourceMission=api;
})(typeof window!=='undefined'?window:globalThis);
